static __inline void projectile_tint_whole_value(effect_color_t &color, float intensity)
{
    if (color.r
            + color.g
            + color.b
        > 1.6f) {
        float tint_scale =
            1.0f - intensity * 0.01f;
        color.r *= tint_scale;
        color.g *= tint_scale;
        color.b *= tint_scale;

        if (color.r < 0.0f) {
            color.r = 0.0f;
        } else if (color.r > 1.0f) {
            color.r = 1.0f;
        }
        if (color.g < 0.0f) {
            color.g = 0.0f;
        } else if (color.g > 1.0f) {
            color.g = 1.0f;
        }
        if (color.b < 0.0f) {
            color.b = 0.0f;
        } else if (color.b > 1.0f) {
            color.b = 1.0f;
        }
        if (color.a < 0.0f) {
            color.a = 0.0f;
        } else if (color.a > 1.0f) {
            color.a = 1.0f;
        }
    }
}

